-- ----------sql1------------
-- -11
SELECT SUM(CASE WHEN U.DISPLAYNAME = 'MORNINGTON' THEN P.VIEWCOUNT ELSE 0 END) - SUM(CASE WHEN U.DISPLAYNAME = 'AMOS' THEN P.VIEWCOUNT ELSE 0 END) AS VIEWCOUNTDIFFERENCE FROM POSTS P JOIN USERS U ON P.OWNERUSERID = U.ID;
-- ----------sql2------------
-- -10
SELECT SUM(IIF(T1.DISPLAYNAME = 'MORNINGTON', T3.VIEWCOUNT, 0)) - SUM(IIF(T1.DISPLAYNAME = 'AMOS', T3.VIEWCOUNT, 0)) AS DIFF FROM USERS AS T1 INNER JOIN POSTHISTORY AS T2 ON T1.ID = T2.USERID INNER JOIN POSTS AS T3 ON T3.ID = T2.POSTID;

