-- ----------sql1------------
-- 2147483651, NULL
SELECT T2.NAME, SUM(T1.HOME_TEAM_GOAL + T1.AWAY_TEAM_GOAL) AS TOTAL_GOALS FROM MATCH AS T1 JOIN LEAGUE AS T2 ON T1.LEAGUE_ID = T2.ID GROUP BY T2.NAME ORDER BY TOTAL_GOALS ASC LIMIT 5;
-- ----------sql2------------
-- 2147483649, NULL
SELECT T1.NAME, SUM(T2.HOME_TEAM_GOAL) + SUM(T2.AWAY_TEAM_GOAL) FROM LEAGUE AS T1 INNER JOIN MATCH AS T2 ON T1.ID = T2.LEAGUE_ID GROUP BY T1.NAME ORDER BY SUM(T2.HOME_TEAM_GOAL) + SUM(T2.AWAY_TEAM_GOAL) ASC LIMIT 5;

